func OaLineMergeMeta(text *port.Cells, joined int32, jn int32, candidate int32, cn int32, tokens int32, lineRetry int32, margin int32, im *port.Cells, cm *port.Cells) int32 {
	if (tokens < 2) || (lineRetry != 1) {
		return 0
	}
	if (oaSpan(text, joined, jn) == 0) || (oaSpan(text, candidate, cn) == 0) {
		return 0
	}
	ofmt.FmtValue(text, candidate, cn, cm)
	if (port.CellsAt(cm, 0) == 0) || (port.CellsAt(cm, 1) != 2) {
		return 0
	}
	var i int32 = joined
	var j int32 = candidate
	var equal int32 = 1
	var first int32 = joined
	var malformed int32 = 0
	for i < (joined + jn) {
		if port.CellsAt(text, i) != 32 {
			if j >= (candidate + cn) {
				equal = 0
			} else if port.CellsAt(text, i) != port.CellsAt(text, j) {
				equal = 0
			}
			j += 1
		}
		i += 1
	}
	if (equal == 1) && (j == (candidate + cn)) {
		return 1
	}
	if margin < 300 {
		return 0
	}
	i = joined
	for i <= (joined + jn) {
		if (i == (joined + jn)) || (port.CellsAt(text, i) == 32) {
			if i > first {
				ofmt.FmtValue(text, first, i-first, im)
				if port.CellsAt(im, 0) == 0 {
					malformed = 1
				}
			}
			first = i + 1
		}
		i += 1
	}
	if malformed == 0 {
		return 0
	}
	if oaCompatible(text, joined, jn, candidate, cn, im, cm) == 1 {
		return 1
	}
	return 0
}

